const COLOR_VENTAS = '#008300';
const COLOR_VENTAS_SUAVE = 'rgba(0, 131, 0, 0.55)';
const COLOR_GASTOS = '#c98500';
const COLOR_CONTEXTO = '#8e8e8e';

const tema = context.grafana.theme;
const colorTexto = tema.colors.text.secondary;
const colorBorde = tema.colors.border.weak;
const marco = context.panel.data.series[0];
// valores de una columna; Grafana los entrega como arreglo (o como vector
// en versiones viejas, por eso el .buffer)
const columna = (nombre) => {
    const campo = marco && marco.fields.find((f) => f.name === nombre);
    return campo ? Array.from(campo.values.buffer || campo.values) : [];
};
const moneda = new Intl.NumberFormat('es-GT', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const entero = new Intl.NumberFormat('es-GT', { maximumFractionDigits: 0 });
const sinDatos = () => ({
    version: 2,
    config: { notMerge: true },
    option: {
        backgroundColor: 'transparent',
        title: {
            text: 'Sin datos en el rango seleccionado',
            left: 'center',
            top: 'middle',
            textStyle: { color: colorTexto, fontSize: 14, fontWeight: 'normal' },
        },
    },
});

const semanas = columna('Semana');
const ventas = columna('Venta total').map(Number);
const enCurso = columna('En curso').map(Number);
if (!semanas.length) return sinDatos();

const cerradas = ventas.filter((v, i) => !enCurso[i]);
const base = cerradas.length ? cerradas : ventas;
const promedio = base.reduce((a, b) => a + b, 0) / base.length;
const pocas = semanas.length <= 16; // con muchas semanas los valores se enciman
const degradado = new context.echarts.graphic.LinearGradient(0, 0, 0, 1, [
    { offset: 0, color: COLOR_VENTAS },
    { offset: 1, color: COLOR_VENTAS_SUAVE },
]);

return {
    version: 2,
    config: { notMerge: true },
    option: {
        backgroundColor: 'transparent',
        tooltip: {
            trigger: 'axis',
            axisPointer: { type: 'shadow' },
            formatter: (p) => {
                const i = p[0].dataIndex;
                return 'Semana del ' + semanas[i] + (enCurso[i] ? ' (en curso)' : '') +
                    '<br/><b>Q ' + moneda.format(ventas[i]) + '</b>';
            },
        },
        grid: { left: 8, right: 16, top: 28, bottom: 8, containLabel: true },
        xAxis: {
            type: 'category',
            data: semanas,
            axisLine: { lineStyle: { color: colorBorde } },
            axisLabel: { color: colorTexto },
        },
        yAxis: {
            type: 'value',
            min: 0,
            splitLine: { lineStyle: { color: colorBorde } },
            axisLabel: { color: colorTexto, formatter: (v) => entero.format(v) },
        },
        series: [{
            type: 'bar',
            barMaxWidth: 48,
            data: ventas.map((v, i) => ({
                value: v,
                itemStyle: { color: degradado, borderRadius: [4, 4, 0, 0], opacity: enCurso[i] ? 0.45 : 1 },
            })),
            label: { show: pocas, position: 'top', color: colorTexto, formatter: (p) => entero.format(p.value) },
            markLine: {
                symbol: 'none',
                silent: true,
                lineStyle: { color: colorTexto, type: 'solid', width: 1, opacity: 0.6 },
                label: { color: colorTexto, position: 'insideEndTop', formatter: 'Promedio: Q ' + entero.format(promedio) },
                data: [{ yAxis: promedio }],
            },
        }],
    },
};

